-        instr.push_back($sformatf("csrw 0x%0x, x%0d", base_pmp_addr + i, scratch_reg[0]));
-        `uvm_info(`gfn, "Loaded the address of <main> section into pmpaddr0", UVM_LOW)
-      end else begin
+      if (i != 0) begin
