+class riscv_zbs_instr extends riscv_instr;
+  `uvm_object_utils(riscv_zbs_instr)
+
+  function new(string name = "");
+    super.new(name);
+  endfunction : new
+
+  function void pre_randomize();
+    super.pre_randomize();
+  endfunction : pre_randomize
+
+  function bit is_rv64();
+    is_rv64 = (group == RV64B);
