+  `ZBA_R_INSTR_CG_BEGIN(sh2add_uw)
+  `CG_END
+  `ZBA_R_INSTR_CG_BEGIN(sh3add_uw)
+  `CG_END
+
   // Count Leading/Trailing Zeros (clz, ctz)
+  `ZBB_I_INSTR_CG_BEGIN(clz)
