+mixin (riscv_va_instr_mixin(VMSLT,    VA_FORMAT, COMPARE, RVV, [VV, VX]));
+mixin (riscv_va_instr_mixin(VMSLEU,   VA_FORMAT, COMPARE, RVV, [VV, VX, VI]));
