diff --git a/riscv/gen/isa/riscv_b_instr.d b/riscv/gen/isa/riscv_b_instr.d
new file mode 100644
index 0000000..b65825d
--- /dev/null
+++ b/riscv/gen/isa/riscv_b_instr.d
@@ -0,0 +1,688 @@
+/*
