+      SBCLR: get_func3 = 3'b001;
+      SBSET: get_func3 = 3'b001;
+      SBINV: get_func3 = 3'b001;
+      SBEXT: get_func3 = 3'b101;
+      GREV: get_func3 = 3'b101;
+      SLOI: get_func3 = 3'b001;
