   rand riscv_fpr_t fd;
+  bit              has_fs1 = 1'b1;
+  bit              has_fs2 = 1'b1;
+  bit              has_fs3 = 1'b0;
+  bit              has_fd  = 1'b1;

   `uvm_object_utils(riscv_floating_point_instr)
-
-  function new(string name = "");
-    super.new(name);
-    rs2.rand_mode(0);
-  endfunction
+  `uvm_object_new

   // Convert the instruction to assembly code
   virtual function string convert2asm(string prefix = "");
@@ -56,15 +72,81 @@ class riscv_floating_point_instr extends riscv_instr;
     return asm_str.tolower();
   endfunction

-
   virtual function void do_copy(uvm_object rhs);
     riscv_floating_point_instr rhs_;
     super.copy(rhs);
     assert($cast(rhs_, rhs));
-    this.fs3            = rhs_.fs3;
-    this.fs2            = rhs_.fs2;
-    this.fs1            = rhs_.fs1;
-    this.fd             = rhs_.fd;
+    this.fs3     = rhs_.fs3;
+    this.fs2     = rhs_.fs2;
+    this.fs1     = rhs_.fs1;
+    this.fd      = rhs_.fd;
+    this.has_fs3 = rhs_.has_fs3;
+    this.has_fs2 = rhs_.has_fs2;
+    this.has_fs1 = rhs_.has_fs1;
+    this.has_fd  = rhs_.has_fd;
   endfunction : do_copy

+  virtual function void set_rand_mode();
+    has_rs1 = 0;
+    has_rs2 = 0;
+    has_rd  = 0;
+    has_imm = 0;
+    case (format)
+      I_FORMAT: begin
+        has_fs2 = 1'b0;
+        if (category == LOAD) begin
+          has_imm = 1'b1;
+        end else if (instr_name inside {FMV_X_W, FMV_X_D, FCVT_W_S, FCVT_WU_S,
+                                        FCVT_L_S, FCVT_LU_S, FCVT_L_D, FCVT_LU_D, FCVT_LU_S,
+                                        FCVT_W_D, FCVT_WU_D}) begin
+          has_fd = 1'b0;
+          has_rd = 1'b1;
+        end else if (instr_name inside {FMV_W_X, FMV_D_X, FCVT_S_W, FCVT_S_WU,
+                                        FCVT_S_L, FCVT_D_L, FCVT_S_LU, FCVT_D_W,
+                                        FCVT_D_LU, FCVT_D_WU}) begin
+          has_rs1 = 1'b1;
+          has_fs1 = 1'b0;
+        end
+      end
+      S_FORMAT: begin
+        has_imm = 1'b1;
+        has_rs1 = 1'b1;
+        has_fs1 = 1'b0;
+        has_fs3 = 1'b0;
+      end
+      R_FORMAT:
+        if (category == COMPARE) begin
+          has_rd = 1'b1;
+          has_fd = 1'b0;
+        end else if (instr_name inside {FCLASS_S, FCLASS_D}) begin
+          has_rd = 1'b1;
+          has_fd = 1'b0;
+          has_fs2 = 1'b0;
+        end
+      R4_FORMAT: begin
+        has_fs3 = 1'b1;
+      end
+      CL_FORMAT: begin
+        has_imm = 1'b1;
+        has_rs1 = 1'b1;
+        has_fs1 = 1'b0;
+        has_fs2 = 1'b0;
+      end
+      CS_FORMAT: begin
+        has_imm = 1'b1;
+        has_rs1 = 1'b1;
+        has_fs1 = 1'b0;
+        has_fd = 1'b0;
+      end
+    endcase
+  endfunction
+
+  function void pre_randomize();
+    super.pre_randomize();
+    fs1.rand_mode(has_fs1);
+    fs2.rand_mode(has_fs2);
+    fs3.rand_mode(has_fs3);
+    fd.rand_mode(has_fd);
+  endfunction
+
 endclass
