+      vs1 != vd + 1;
+    }
+    if (has_vs2) {
+      vs2 != vd;
+      vs2 != vd + 1;
+    }
+  }
+
+  // rs2 is double-width source register
+  // The destination vector register group cannot overlap the rst source
+  // vector register group (specied by vs2)
+  constraint narrowing_instr_c {
+    if (has_vs2) {
+      int'(vs2) % 2 == 0;
+      vd != vs2;
+      vd != vs2 + 1;
+    }
+  }
