-      offset[i] = offset_;
-      addr[i] = addr_;
-    end
-  endfunction
-
-  function void post_randomize();
-    randomize_offset();
-    // rs1 cannot be modified by other instructions
-    if(!(rs1_reg inside {reserved_rd})) begin
-      reserved_rd = {reserved_rd, rs1_reg};
