   `include "riscv_directed_instr_lib.sv"
   `include "riscv_load_store_instr_lib.sv"
   `include "riscv_amo_instr_lib.sv"
+`endif
   `include "riscv_instr_sequence.sv"
   `include "riscv_asm_program_gen.sv"
   `include "riscv_instr_cov_item.sv"
