+        if (cfg.init_privileged_mode == MACHINE_MODE) {
+          csr == MSCRATCH;
+        } else if (cfg.init_privileged_mode == SUPERVISOR_MODE) {
+          csr == SSCRATCH;
+        } else {
+          csr == USCRATCH;
+        }
+      }
+    }
+  }
+
   `uvm_object_new

 endclass
